// Scoped enum with a specified 1-byte underlying type.
enum class Color : unsigned char {
    Red, Green, Blue
};

// Unscoped enum with a specified 4-byte underlying type.
enum LegacyStatus : unsigned int {
    OK = 0,
    Error = 1
};

// Scoped enum using the default underlying type (int).
enum class Alert {
    Warning,
    Critical
};
